export function shuffle(items, random = Math.random) {
  const result = [...items];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}
export function createAttempt(id) {
  const quiz = quizzes[id];
  if (!quiz) throw new Error('Неизвестный тест');
  return { version: 1, quiz: id, index: 0, complete: false, answers: {}, order: Object.fromEntries(quiz.questions.map(q => [q.id, shuffle(q.options.map(o => o.id))])) };
}
export function validAttempt(value, id) {
  const quiz = quizzes[id];
  if (!quiz || !value || value.version !== 1 || value.quiz !== id || typeof value.complete !== 'boolean' || !Number.isInteger(value.index) || value.index < 0 || value.index >= quiz.questions.length) return false;
  if (!value.answers || typeof value.answers !== 'object' || Array.isArray(value.answers) || !value.order || typeof value.order !== 'object' || Array.isArray(value.order)) return false;
  if (Object.keys(value.order).length !== quiz.questions.length) return false;
  if (Object.entries(value.answers).some(([id, answer]) => !quiz.questions.some(q => q.id === id && q.options.some(o => o.id === answer)))) return false;
  return quiz.questions.every(q => Array.isArray(value.order[q.id]) && value.order[q.id].length === 4 && new Set(value.order[q.id]).size === 4 && value.order[q.id].every(id => q.options.some(o => o.id === id)));
}
export function calculateResult(quiz, answers) {
  let correct = 0, wrong = 0, skipped = 0;
  const rows = quiz.questions.map(q => {
    const selected = q.options.find(o => o.id === answers[q.id]);
    const outcome = !selected ? 'skipped' : selected.id === q.correctId ? 'correct' : 'wrong';
    if (outcome === 'correct') correct++;
    else if (outcome === 'wrong') wrong++;
    else skipped++;
    return { question: q, selected, correct: q.options.find(o => o.id === q.correctId), outcome };
  });
  const title = correct === 15 ? 'Все ответы совпали' : correct >= 12 ? 'Ты помнишь большинство деталей' : correct >= 8 ? 'Часть деталей ты помнишь, часть можно обсудить' : 'Есть несколько историй, которые стоит рассказать друг другу';
  return { correct, wrong, skipped, total: quiz.questions.length, percent: Math.round(correct / quiz.questions.length * 100), title, rows };
}
